create schema if not exists manager_private;
revoke all on schema manager_private from public,anon;
grant usage on schema manager_private to authenticated;
create table manager_private.bootstrap (email text primary key, claimed_by uuid references auth.users(id), created_at timestamptz not null default now());
alter table manager_private.bootstrap enable row level security;
create table public.staff_profiles (
 user_id uuid primary key references auth.users(id) on delete restrict,
 display_name text not null check(length(trim(display_name)) between 1 and 80),
 role text not null check(role in ('owner','manager','staff')),
 secret_access boolean not null default false, active boolean not null default true,
 created_at timestamptz not null default now(), updated_at timestamptz not null default clock_timestamp()
);
create table public.materials (
 id bigint generated by default as identity primary key,
 name text not null check(length(trim(name)) between 1 and 120),vendor text check(length(vendor)<=200),
 purchase_url text check(purchase_url is null or (purchase_url ~ '^https?://' and length(purchase_url)<=2000)),
 purchase_price numeric(14,2) check(purchase_price>=0 and purchase_price<100000000000),
 purchase_quantity numeric(16,6) check(purchase_quantity>0 and purchase_quantity<1000000000),
 unit text not null check(unit in ('g','kg','ml','L','개')),
 updated_at timestamptz not null default clock_timestamp(),
 check(purchase_price is null or purchase_quantity is not null)
);
create table public.recipes(id bigint generated by default as identity primary key,name text not null check(length(trim(name)) between 1 and 120),selling_price numeric(14,2) not null check(selling_price>=0 and selling_price<100000000000),instructions text not null default '' check(length(instructions)<=10000),updated_at timestamptz not null default clock_timestamp());
create table public.secret_recipes(id bigint generated by default as identity primary key,name text not null check(length(trim(name)) between 1 and 120),yield_quantity numeric(16,6) not null check(yield_quantity>0 and yield_quantity<1000000000),yield_unit text not null check(yield_unit in ('g','ml','개')),instructions text not null default '' check(length(instructions)<=10000),updated_at timestamptz not null default clock_timestamp());
create table public.recipe_items(id bigint generated by default as identity primary key,recipe_id bigint not null references public.recipes(id) on delete cascade,material_id bigint references public.materials(id) on delete restrict,secret_recipe_id bigint references public.secret_recipes(id) on delete restrict,amount numeric(16,6) not null check(amount>0 and amount<1000000000),check(num_nonnulls(material_id,secret_recipe_id)=1));
create index recipe_items_recipe_idx on public.recipe_items(recipe_id);
create index recipe_items_material_idx on public.recipe_items(material_id);
create index recipe_items_secret_idx on public.recipe_items(secret_recipe_id);
create table public.secret_recipe_items(id bigint generated by default as identity primary key,secret_recipe_id bigint not null references public.secret_recipes(id) on delete cascade,material_id bigint not null references public.materials(id) on delete restrict,amount numeric(16,6) not null check(amount>0 and amount<1000000000));
create index secret_items_recipe_idx on public.secret_recipe_items(secret_recipe_id);
create index secret_items_material_idx on public.secret_recipe_items(material_id);
create table public.material_price_history(id bigint generated by default as identity primary key,material_id bigint not null references public.materials(id) on delete restrict,price numeric(14,2) not null check(price>=0 and price<100000000000),purchase_quantity numeric(16,6) not null check(purchase_quantity>0),unit text not null check(unit in ('g','kg','ml','L','개')),source text not null default 'manual',recorded_at timestamptz not null default clock_timestamp(),recorded_by uuid references auth.users(id));
create index history_material_date_idx on public.material_price_history(material_id,recorded_at desc);
create table public.access_audit(id bigint generated by default as identity primary key,actor uuid references auth.users(id),target uuid references auth.users(id),action text not null,details jsonb not null default '{}',created_at timestamptz not null default now());
create table manager_private.invitations(email text primary key,display_name text not null,role text not null check(role in ('manager','staff')),invited_by uuid not null references auth.users(id),created_at timestamptz not null default now());
alter table manager_private.invitations enable row level security;
create function manager_private.is_active() returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and exists(select 1 from public.staff_profiles p join auth.users u on u.id=p.user_id where p.user_id=auth.uid() and p.active and u.email_confirmed_at is not null) $$;
create function manager_private.is_owner() returns boolean language sql stable security definer set search_path='' as $$ select manager_private.is_active() and exists(select 1 from public.staff_profiles where user_id=auth.uid() and role='owner') $$;
create function manager_private.is_editor() returns boolean language sql stable security definer set search_path='' as $$ select manager_private.is_active() and exists(select 1 from public.staff_profiles where user_id=auth.uid() and role in ('owner','manager')) $$;
create function manager_private.can_secret() returns boolean language sql stable security definer set search_path='' as $$ select manager_private.is_active() and exists(select 1 from public.staff_profiles where user_id=auth.uid() and (role='owner' or secret_access)) $$;
alter table public.staff_profiles enable row level security;
create policy profile_read on public.staff_profiles for select to authenticated using (user_id=(select auth.uid()) or (select manager_private.is_owner()));
do $$ declare t text; begin foreach t in array array['materials','recipes','recipe_items','material_price_history'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy editor_read on public.%I for select to authenticated using ((select manager_private.is_editor()))',t);end loop; foreach t in array array['secret_recipes','secret_recipe_items'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy secret_read on public.%I for select to authenticated using ((select manager_private.is_editor()) and (select manager_private.can_secret()))',t);end loop;end $$;
alter table public.access_audit enable row level security;
create policy audit_owner_read on public.access_audit for select to authenticated using ((select manager_private.is_owner()));
revoke all on public.staff_profiles,public.materials,public.recipes,public.recipe_items,public.secret_recipes,public.secret_recipe_items,public.material_price_history,public.access_audit from anon,authenticated;
grant select on public.staff_profiles,public.materials,public.recipes,public.recipe_items,public.secret_recipes,public.secret_recipe_items,public.material_price_history,public.access_audit to authenticated;
create function manager_private.activate_owner() returns boolean language plpgsql security definer set search_path='' as $$
declare e text; begin
 if auth.uid() is null then raise exception '로그인이 필요합니다.' using errcode='42501'; end if;
 select lower(email) into e from auth.users where id=auth.uid() and email_confirmed_at is not null;
 perform 1 from manager_private.bootstrap where email=e for update;
 if not found then return false;end if;
 if exists(select 1 from public.staff_profiles where role='owner' and user_id<>auth.uid()) then return false;end if;
 if exists(select 1 from manager_private.bootstrap where email=e and claimed_by is not null and claimed_by<>auth.uid()) then return false;end if;
 insert into public.staff_profiles(user_id,display_name,role,secret_access) values(auth.uid(),'대표자','owner',true) on conflict(user_id) do nothing;
 update manager_private.bootstrap set claimed_by=auth.uid() where email=e;
 return true;
end $$;
create function manager_private.save_material(p_id bigint,p_row jsonb,p_expected timestamptz) returns bigint language plpgsql security definer set search_path='' as $$
declare old public.materials; newrow public.materials; begin
 if not manager_private.is_editor() then raise exception '관리 권한이 필요합니다.' using errcode='42501';end if;
 if p_id is not null then select * into old from public.materials where id=p_id for update;if not found then raise exception '원자재를 찾을 수 없습니다.';end if;if p_expected is null or old.updated_at<>p_expected then raise exception '다른 화면에서 변경됐습니다. 새로고침 후 다시 저장하세요.' using errcode='40001';end if;end if;
 if p_id is null then
 insert into public.materials(name,vendor,purchase_url,purchase_price,purchase_quantity,unit) values(trim(p_row->>'name'),nullif(trim(p_row->>'vendor'),''),nullif(trim(p_row->>'purchase_url'),''),(p_row->>'purchase_price')::numeric,(p_row->>'purchase_quantity')::numeric,p_row->>'unit') returning * into newrow;
 else
 update public.materials set name=trim(p_row->>'name'),vendor=nullif(trim(p_row->>'vendor'),''),purchase_url=nullif(trim(p_row->>'purchase_url'),''),purchase_price=(p_row->>'purchase_price')::numeric,purchase_quantity=(p_row->>'purchase_quantity')::numeric,unit=p_row->>'unit',updated_at=clock_timestamp() where id=p_id returning * into newrow;
 end if;
 if newrow.purchase_price is not null and (p_id is null or row(old.purchase_price,old.purchase_quantity,old.unit) is distinct from row(newrow.purchase_price,newrow.purchase_quantity,newrow.unit)) then
 insert into public.material_price_history(material_id,price,purchase_quantity,unit,recorded_by) values(newrow.id,newrow.purchase_price,newrow.purchase_quantity,newrow.unit,auth.uid());end if;
 return newrow.id;
end $$;
create function manager_private.save_recipe(p_id bigint,p_row jsonb,p_items jsonb,p_secret boolean,p_expected timestamptz) returns bigint language plpgsql security definer set search_path='' as $$
declare parent_id bigint; old_time timestamptz; old_secret_ids bigint[]; new_secret_ids bigint[]; begin
 if not manager_private.is_editor() or (p_secret and not manager_private.can_secret()) then raise exception '저장 권한이 없습니다.' using errcode='42501';end if;
 if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 100 then raise exception '재료는 1~100개 입력하세요.';end if;
 if p_secret then
  if p_id is null then insert into public.secret_recipes(name,yield_quantity,yield_unit,instructions) values(trim(p_row->>'name'),(p_row->>'yield_quantity')::numeric,p_row->>'yield_unit',coalesce(p_row->>'instructions','')) returning id into parent_id;
  else select updated_at into old_time from public.secret_recipes where id=p_id for update;if not found then raise exception '레시피 없음';end if;if p_expected is null or old_time<>p_expected then raise exception '다른 화면에서 변경됐습니다. 새로고침 후 다시 저장하세요.' using errcode='40001';end if;parent_id:=p_id;update public.secret_recipes set name=trim(p_row->>'name'),yield_quantity=(p_row->>'yield_quantity')::numeric,yield_unit=p_row->>'yield_unit',instructions=coalesce(p_row->>'instructions',''),updated_at=clock_timestamp() where id=p_id;end if;
  delete from public.secret_recipe_items where secret_recipe_id=parent_id;
  insert into public.secret_recipe_items(secret_recipe_id,material_id,amount) select parent_id,(x->>'material_id')::bigint,(x->>'amount')::numeric from jsonb_array_elements(p_items) x;
 else
  if not manager_private.can_secret() then
   select coalesce(array_agg(secret_recipe_id order by secret_recipe_id),'{}') into old_secret_ids from public.recipe_items where recipe_id=p_id and secret_recipe_id is not null;
   select coalesce(array_agg((x->>'secret_recipe_id')::bigint order by (x->>'secret_recipe_id')::bigint),'{}') into new_secret_ids from jsonb_array_elements(p_items)x where x->>'secret_recipe_id' is not null;
   if old_secret_ids is distinct from new_secret_ids then raise exception '제조 재료 추가·삭제는 비밀 레시피 권한이 필요합니다.' using errcode='42501';end if;
  end if;
  if p_id is null then insert into public.recipes(name,selling_price,instructions) values(trim(p_row->>'name'),(p_row->>'selling_price')::numeric,coalesce(p_row->>'instructions','')) returning id into parent_id;
  else select updated_at into old_time from public.recipes where id=p_id for update;if not found then raise exception '레시피 없음';end if;if p_expected is null or old_time<>p_expected then raise exception '다른 화면에서 변경됐습니다. 새로고침 후 다시 저장하세요.' using errcode='40001';end if;parent_id:=p_id;update public.recipes set name=trim(p_row->>'name'),selling_price=(p_row->>'selling_price')::numeric,instructions=coalesce(p_row->>'instructions',''),updated_at=clock_timestamp() where id=p_id;end if;
  delete from public.recipe_items where recipe_id=parent_id;
  insert into public.recipe_items(recipe_id,material_id,secret_recipe_id,amount) select parent_id,(x->>'material_id')::bigint,(x->>'secret_recipe_id')::bigint,(x->>'amount')::numeric from jsonb_array_elements(p_items)x;
 end if;
 return parent_id;
end $$;
create function manager_private.set_staff_access(p_user uuid,p_role text,p_secret boolean,p_active boolean) returns void language plpgsql security definer set search_path='' as $$
declare old public.staff_profiles;begin
 if not manager_private.is_owner() then raise exception '대표자만 변경할 수 있습니다.' using errcode='42501';end if;
 select * into old from public.staff_profiles where user_id=p_user for update;
 if not found or old.role='owner' or p_user=auth.uid() or p_role not in ('manager','staff') or p_secret is null or p_active is null then raise exception '변경할 수 없는 계정 또는 권한입니다.';end if;
 update public.staff_profiles set role=p_role,secret_access=p_secret,active=p_active,updated_at=clock_timestamp() where user_id=p_user;
 insert into public.access_audit(actor,target,action,details) values(auth.uid(),p_user,'access_updated',jsonb_build_object('old',jsonb_build_object('role',old.role,'secret_access',old.secret_access,'active',old.active),'new',jsonb_build_object('role',p_role,'secret_access',p_secret,'active',p_active)));
end $$;
create function manager_private.material_cost(p_id bigint,p_amount numeric) returns numeric language sql stable set search_path='' as $$ select case when purchase_price is not null and purchase_quantity>0 then purchase_price/(purchase_quantity*case when unit in ('kg','L') then 1000 else 1 end)*p_amount end from public.materials where id=p_id $$;
create function manager_private.secret_cost(p_id bigint) returns numeric language sql stable set search_path='' as $$ select case when count(*)>0 and count(*)=count(manager_private.material_cost(material_id,amount)) then sum(manager_private.material_cost(material_id,amount)) end from public.secret_recipe_items where secret_recipe_id=p_id $$;
create function manager_private.recipe_cost(p_id bigint) returns numeric language sql stable set search_path='' as $$ select case when count(*)>0 and count(*)=count(c) then sum(c) end from (select case when i.material_id is not null then manager_private.material_cost(i.material_id,i.amount) else manager_private.secret_cost(i.secret_recipe_id)/s.yield_quantity*i.amount end c from public.recipe_items i left join public.secret_recipes s on s.id=i.secret_recipe_id where i.recipe_id=p_id)q $$;
create function manager_private.management_snapshot() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin
 if not manager_private.is_editor() then raise exception '관리 권한이 필요합니다.' using errcode='42501';end if;
 return jsonb_build_object('materials',coalesce((select jsonb_agg(m order by m.id) from public.materials m),'[]'),'recipes',coalesce((select jsonb_agg(r order by r.id) from public.recipes r),'[]'),'recipe_items',coalesce((select jsonb_agg(i order by i.id) from public.recipe_items i),'[]'),'material_price_history',coalesce((select jsonb_agg(h order by h.id) from public.material_price_history h),'[]'),'secret_recipes',coalesce((select jsonb_agg(case when manager_private.can_secret() then to_jsonb(s) else jsonb_build_object('id',s.id,'name',s.name,'yield_quantity',s.yield_quantity,'yield_unit',s.yield_unit) end order by s.id) from public.secret_recipes s),'[]'),'secret_recipe_items',case when manager_private.can_secret() then coalesce((select jsonb_agg(i order by i.id) from public.secret_recipe_items i),'[]') else '[]'::jsonb end,'recipe_costs',coalesce((select jsonb_object_agg(id::text,manager_private.recipe_cost(id)) from public.recipes),'{}'),'secret_costs',coalesce((select jsonb_object_agg(id::text,manager_private.secret_cost(id)) from public.secret_recipes),'{}'));
end $$;
create function manager_private.staff_recipe_view() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin
 if not manager_private.is_active() then raise exception '활성 직원 계정이 필요합니다.' using errcode='42501';end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'name',r.name,'instructions',r.instructions,'ingredients',coalesce((select jsonb_agg(jsonb_build_object('name',coalesce(m.name,s.name),'amount',i.amount,'unit',coalesce(case m.unit when 'kg' then 'g' when 'L' then 'ml' else m.unit end,s.yield_unit)) order by i.id) from public.recipe_items i left join public.materials m on m.id=i.material_id left join public.secret_recipes s on s.id=i.secret_recipe_id where i.recipe_id=r.id),'[]')) order by r.id) from public.recipes r),'[]') || case when manager_private.can_secret() then coalesce((select jsonb_agg(jsonb_build_object('id','secret:'||r.id,'name','[승인 배합] '||r.name,'instructions',r.instructions,'ingredients',coalesce((select jsonb_agg(jsonb_build_object('name',m.name,'amount',i.amount,'unit',case m.unit when 'kg' then 'g' when 'L' then 'ml' else m.unit end) order by i.id) from public.secret_recipe_items i join public.materials m on m.id=i.material_id where i.secret_recipe_id=r.id),'[]')) order by r.id) from public.secret_recipes r),'[]') else '[]'::jsonb end;
end $$;
create function public.activate_owner() returns boolean language sql security invoker set search_path='' as $$select manager_private.activate_owner()$$;
create function public.save_material(p_id bigint,p_row jsonb,p_expected timestamptz default null) returns bigint language sql security invoker set search_path='' as $$select manager_private.save_material(p_id,p_row,p_expected)$$;
create function public.save_recipe(p_id bigint,p_row jsonb,p_items jsonb,p_secret boolean default false,p_expected timestamptz default null) returns bigint language sql security invoker set search_path='' as $$select manager_private.save_recipe(p_id,p_row,p_items,p_secret,p_expected)$$;
create function public.set_staff_access(p_user uuid,p_role text,p_secret boolean,p_active boolean) returns void language sql security invoker set search_path='' as $$select manager_private.set_staff_access(p_user,p_role,p_secret,p_active)$$;
create function public.management_snapshot() returns jsonb language sql security invoker set search_path='' as $$select manager_private.management_snapshot()$$;
create function public.staff_recipe_view() returns jsonb language sql security invoker set search_path='' as $$select manager_private.staff_recipe_view()$$;
revoke all on all tables in schema manager_private from public,anon,authenticated;
revoke all on all functions in schema manager_private from public,anon,authenticated;
revoke all on function public.activate_owner(),public.save_material(bigint,jsonb,timestamptz),public.save_recipe(bigint,jsonb,jsonb,boolean,timestamptz),public.set_staff_access(uuid,text,boolean,boolean),public.management_snapshot(),public.staff_recipe_view() from public,anon;
grant execute on function manager_private.is_active(),manager_private.is_owner(),manager_private.is_editor(),manager_private.can_secret(),manager_private.activate_owner(),manager_private.save_material(bigint,jsonb,timestamptz),manager_private.save_recipe(bigint,jsonb,jsonb,boolean,timestamptz),manager_private.set_staff_access(uuid,text,boolean,boolean),manager_private.management_snapshot(),manager_private.staff_recipe_view() to authenticated;
grant execute on function public.activate_owner(),public.save_material(bigint,jsonb,timestamptz),public.save_recipe(bigint,jsonb,jsonb,boolean,timestamptz),public.set_staff_access(uuid,text,boolean,boolean),public.management_snapshot(),public.staff_recipe_view() to authenticated;
-- Only the email explicitly chosen by the owner may activate the first owner account.
-- Provision the user-confirmed owner email separately through a privileged session.
notify pgrst,'reload schema';
